package com.careerpilot.careerplan;
import com.careerpilot.modules.careerrecommendation.client.CareerPredictionClient;import com.fasterxml.jackson.databind.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.ArgumentMatchers.any;import static org.mockito.Mockito.when;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:careerplan;MODE=PostgreSQL;DB_CLOSE_DELAY=-1","spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password=","spring.jpa.hibernate.ddl-auto=create-drop","spring.flyway.enabled=false"})@AutoConfigureMockMvc@ActiveProfiles("test")class CareerPlanFlowIntegrationTest{
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;@MockitoBean CareerPredictionClient predictions;
 @Test void createsOwnedPlanPersistsSelectionAndUserReportedProgress()throws Exception{String owner=register("plan-owner@example.com"),other=register("plan-other@example.com");complete(owner);when(predictions.predict(any())).thenReturn(prediction("Backend Developer"));JsonNode recommendation=createRecommendation(owner);String request=json.writeValueAsString(Map.of("recommendationId",recommendation.path("id").asText(),"career","Backend Developer"));mvc.perform(post("/api/v1/career-plans").header("Authorization",other).contentType("application/json").content(request)).andExpect(status().isNotFound());JsonNode plan=json.readTree(mvc.perform(post("/api/v1/career-plans").header("Authorization",owner).contentType("application/json").content(request)).andExpect(status().isCreated()).andExpect(jsonPath("$.selectedCareer").value("Backend Developer")).andExpect(jsonPath("$.taxonomyVersion").value("career-skill-taxonomy-v1")).andExpect(jsonPath("$.placementReadiness.components[2].status").value("UNAVAILABLE")).andExpect(jsonPath("$.skillGap.missingCore").isArray()).andReturn().getResponse().getContentAsString());String itemId=plan.path("roadmap").get(0).path("id").asText();mvc.perform(patch("/api/v1/career-plans/items/{id}",itemId).header("Authorization",owner).contentType("application/json").content("{\"status\":\"IN_PROGRESS\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.roadmap[0].status").value("IN_PROGRESS")).andExpect(jsonPath("$.roadmap[0].statusSource").value("USER_REPORTED"));mvc.perform(get("/api/v1/career-plans/current").header("Authorization",owner)).andExpect(status().isOk()).andExpect(jsonPath("$.selectedCareer").value("Backend Developer")).andExpect(jsonPath("$.roadmap[0].status").value("IN_PROGRESS"));mvc.perform(patch("/api/v1/career-plans/items/{id}",itemId).header("Authorization",other).contentType("application/json").content("{\"status\":\"READY\"}")).andExpect(status().isNotFound());}
 @Test void rejectsUnsupportedOrUnrecommendedCareer()throws Exception{String auth=register("plan-invalid@example.com");complete(auth);when(predictions.predict(any())).thenReturn(prediction("Space Wizard"));JsonNode recommendation=createRecommendation(auth);String body=json.writeValueAsString(Map.of("recommendationId",recommendation.path("id").asText(),"career","Space Wizard"));mvc.perform(post("/api/v1/career-plans").header("Authorization",auth).contentType("application/json").content(body)).andExpect(status().isBadRequest()).andExpect(jsonPath("$.message").value("Unsupported career"));body=json.writeValueAsString(Map.of("recommendationId",recommendation.path("id").asText(),"career","Backend Developer"));mvc.perform(post("/api/v1/career-plans").header("Authorization",auth).contentType("application/json").content(body)).andExpect(status().isBadRequest());}
 private CareerPredictionClient.PredictionResponse prediction(String first){return new CareerPredictionClient.PredictionResponse("test-model","profile-features-v1",List.of(new CareerPredictionClient.PredictionItem(first,.7,List.of("Profile skill: Java")),new CareerPredictionClient.PredictionItem("QA Automation Engineer",.2,List.of()),new CareerPredictionClient.PredictionItem("Data Analyst",.1,List.of())));}
 private JsonNode createRecommendation(String auth)throws Exception{return json.readTree(mvc.perform(post("/api/v1/career-recommendations").header("Authorization",auth)).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString());}
 private void complete(String auth)throws Exception{mvc.perform(patch("/api/v1/profile").header("Authorization",auth).contentType("application/json").content("{\"degree\":\"B.Tech\",\"targetRole\":\"Backend Developer\",\"experienceLevel\":\"ENTRY_LEVEL\"}")).andExpect(status().isOk());mvc.perform(put("/api/v1/profile/skills").header("Authorization",auth).contentType("application/json").content("{\"skills\":[{\"displayName\":\"Java\",\"proficiencyLevel\":\"BEGINNER\"},{\"displayName\":\"Spring Boot\",\"proficiencyLevel\":\"INTERMEDIATE\"},{\"displayName\":\"Docker\",\"proficiencyLevel\":\"ADVANCED\"}]}")).andExpect(status().isOk());}
 private String register(String email)throws Exception{String body="{\"fullName\":\"Plan Test\",\"email\":\""+email+"\",\"password\":\"Password1\",\"confirmPassword\":\"Password1\"}";JsonNode response=json.readTree(mvc.perform(post("/api/v1/auth/register").contentType("application/json").content(body)).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString());return"Bearer "+response.path("accessToken").asText();}
}
